#!/usr/bin/env python3
"""Extract lib/math/int_log.c's 256-entry log table into a C header.

From port/pristine/, not from the kernel tree: the tree's copy is OUR ported
file and no longer has the table. An oracle read out of the ported file is a
test agreeing with itself.
"""
import re
import sys

src = open(sys.argv[1]).read()
m = re.search(r"static const unsigned short logtable\[256\] = \{(.*?)\};", src, re.S)
if not m:
    sys.exit("could not find logtable[256] in " + sys.argv[1])
open(sys.argv[2], "w").write(
    "/* GENERATED by extract_logtable.py from lib/math/int_log.c. Do not edit. */\n"
    "static const unsigned short ref_logtable[256] = {" + m.group(1) + "};\n"
)
